import time
import requests
import os
from .Types import Message, CallbackQuery


class Bot:
    def __init__(self, token):
        self.token = token
        self.api = f"https://tapi.bale.ai/bot{token}"
        self.session = requests.Session()

    def request(self, method_name, data=None):
        url = f"{self.api}/{method_name}"
        try:
            response = self.session.post(url, json=data, timeout=30)
            return response.json()

        except requests.exceptions.RequestException as e:
            print(f"⚠️ Request Error [{method_name}]: {e}")
            return None
        except Exception as e:
            print(f"❌ Unexpected Error: {e}")
            return None

    def send_message(self, chat_id, text, reply_markup=None, reply_to_message_id=None):
        payload = {"chat_id": chat_id, "text": text}

        if reply_markup:
            payload["reply_markup"] = reply_markup

        if reply_to_message_id:
            payload["reply_to_message_id"] = reply_to_message_id

        return self.request("sendMessage", data=payload)

    def delete_webhook(self):
        return self.request("deleteWebhook")

    def start_polling(self, dp, skip_updates=True):
        self.delete_webhook()

        if skip_updates:
            self.request("getUpdates", data={"offset": -1, "timeout": 1})

        offset = 0
        print("🚀 Bot Started Successfully!")
        print("📡 Listening for messages... (Press Ctrl+C to stop)")

        try:
            while True:
                try:
                    updates = self.request(
                        "getUpdates",
                        data={
                            "offset": offset,
                            "limit": 100,
                            "timeout": 20,
                        },
                    )

                    if not updates or not updates.get("ok"):
                        time.sleep(1)
                        continue

                    for upd in updates.get("result", []):
                        offset = upd["update_id"] + 1

                        if "message" in upd:
                            message = Message(self, upd["message"])
                            dp.process(message)

                        elif "callback_query" in upd:
                            cb_query = CallbackQuery(self, upd["callback_query"])
                            cb_query.message.text = cb_query.callback_data

                            print(f"🖱️ Click Detected! Data: {cb_query.callback_data}")
                            dp.process(cb_query.message)

                except Exception as e:
                    print(f"\n⚠️ {e}")
                    time.sleep(5)

        except KeyboardInterrupt:
            print("\n🛑 Stop Signal Received!")
            print(f"👋 GoodBye!")
            os._exit(0)
